pub fn string(&mut self, k: &str, fallback: &str) -> String {
    let Ok(raw) = self.read(k) else {
        return String::new();
    };
    let p = raw.is_some();
    let v = raw.filter(|v| !v.is_empty()).unwrap_or_else(|| fallback.into());
    self.record(k, &v, p, false);
